      "inject_refs": ["S1-I1"],
      "rationale": {
        "observation": "CHG-1 was a planned change to core site A, scheduled to apply in 3 minutes, with no mention of advance customer or regulator notice.",
        "rule": "UAE-LIC-2-2026#0085 requires advance notice to TDRA, interconnecting operators and customers for planned interruptions other than minor interruptions.",
        "inference": "OpCo had a duty to provide that advance notice before the planned change/interruption took effect."
