    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No UAE rule in the provided excerpts requires a sandbox or staged validation before an auto-approved network configuration change is applied to a live core site.",
      "inject_refs": ["S1-I1"],
      "rationale": {
        "observation": "CHG-1 was auto-approved, sandbox stage skipped, and applied to live core site A.",
        "rule": "The closest UAE text, UAE-PDPL#0066, requires pre-processing impact assessment only for high-risk personal data processing, not network configuration changes.",
        "inference": "There is no provided UAE rule requiring a sandbox or staged validation before applying a live network configuration change."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "1. Taking into account the nature, scope and purposes of data processing, the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "AU-ACMA-TELSTRA-2024#0001",
          "quote": "As Australia’s national operator of the Triple Zero service, Telstra is required to comply with obligations set out in the Telecommunications (Emergency Call Service) Determination 2019. The Determination imposes requirements in relation to the handling and transfer of calls made to emergency service numbers."
        }
      ]
    },
    {
      "type": "share",
      "to": ["EMS", "REG"],
      "inject_refs": ["S1-I2", "S1-FB03"],
      "statement": "Passing the R2 emergency-call routing outage and the post-wilt restoration status to EMS and TDRA."
    },
    {
      "type": "insufficient_evidence",
      "statement": "The excerpts do not state whether OpCo must notify EMS or other authorities of an unplanned outage affecting emergency-call routing.",
      "inject_refs": ["S1-I2"],
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "In the case of a planned interruption of a Telecommunication Service other than a minor interruption, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers in advance of such interruption. The Licensee shall specify the reason(s) for the interruption as well as the manner and time frames in which the interruption will be resolved."
        }
      ]
    }
  ]
}

